#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int hasdig(long long v,int d){if(v==0)return d==0;while(v){if(v%10==d)return 1;v/=10;}return 0;}int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);long long c=0;for(i=0;i<n;i++){long long x=a[i];if(hasdig(x, 0))c++;}printf("%lld\n",c);return 0;}
